        requires arr != null && |arr| > 0 && 1 <= k <= |arr|
        ensures 0 <= SumElementsWithTwoDigits(arr, k) <= 2 * k * 99 // Since at most two digits numbers range from 0 to 99
    {
        var sum := 0;
        var count := 0;
        // Iterate through the first k elements
        while count < k
            invariant 0 <= count <= k
            invariant sum == SumElementsWithTwoDigits(arr, count)
        {
            if arr[count] >= -99 && arr[count] <= 99 {
                sum := sum + arr[count];
            }
            count := count + 1;
        }
        return sum;
